//! Pre-issued grants (Genesis Mesh 1.6.0): the shared conformance suite
//! `grants`, generated by the Python reference
//! (genesismesh/conformance/grants_vectors.py) and copied unchanged, and this
//! crate's grant records and checks.

use std::collections::BTreeSet;

use chrono::{DateTime, Utc};
use genesis_mesh_sdk::{
    canonical::received_canonical,
    grants::{
        envelope_problem, grant_digest, normalize_parameter, signed_as_received, use_problem,
        PreviousUse, UseContext,
    },
    json, parse_strict_json,
    verify::{
        parse_export_lines, valid_grant_record, verify_evidence_events, verify_record,
        verify_revocation_feed, VerifyEvidenceOptions, VerifyRecordOptions,
    },
    Value,
};
use sha2::{Digest, Sha256};

fn suite() -> Value {
    serde_json::from_str(include_str!("fixtures/grants.json")).unwrap()
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_owned())
        .collect()
}

fn at(value: &Value) -> Option<DateTime<Utc>> {
    value.as_str().map(|s| s.parse().unwrap())
}

const COUNTS: [&str; 7] = [
    "executions",
    "observations",
    "judgements",
    "quarantined",
    "grants",
    "grant_executions",
    "grant_revocations",
];

/// What this crate makes of one vector, in the form the reference's
/// `evaluate` returns.
fn evaluate(v: &Value) -> Value {
    let input = &v["input"];
    match v["kind"].as_str().unwrap() {
        "canonical_form" => {
            let body = received_canonical(v["model"].as_str().unwrap(), &v["record"]).unwrap();
            let digest: String = Sha256::digest(body.as_bytes())
                .iter()
                .map(|b| format!("{b:02x}"))
                .collect();
            json!({"canonical": body, "digest": digest})
        }
        "verify_record" => json!({"valid": signed_as_received(
            v["model"].as_str().unwrap(),
            &v["record"],
            &[v["public_key"].as_str().unwrap().to_owned()],
        )}),
        "envelope_parameter" => {
            // JSON text for an input a strict reader refuses (an integer
            // beyond 64 bits): refused either way.
            let parameter = match input.get("parameter_json").and_then(Value::as_str) {
                Some(text) => parse_strict_json(text),
                None => Ok(input["parameter"].clone()),
            };
            match parameter.map(|p| normalize_parameter(&p)) {
                Ok(Ok(normalized)) => json!({"valid": true, "normalized": normalized}),
                _ => json!({"valid": false}),
            }
        }
        "envelope" => json!({
            "within": envelope_problem(&input["envelope"], &input["request_parameters"]).is_none()
        }),
        "use" => {
            let previous = input["previous"].as_object().map(|p| PreviousUse {
                executed_at: at(&p["executed_at"]).unwrap(),
                time_token_issued_at: at(&p["time_token_issued_at"]).unwrap(),
            });
            let head = &input["token_head"];
            let keys = strings(&input["na_public_keys"]);
            let context = UseContext {
                grant: Some(&input["grant"]).filter(|g| !g.is_null()),
                previous: previous.as_ref(),
                admitted: input["admitted"].as_u64(),
                token_head: head["digest"]
                    .as_str()
                    .map(|d| (d, at(&head["executed_at"]).unwrap())),
                token_keys: &keys,
                revoked_at: at(&input["revoked_at"]),
                recorded_at: at(&input["recorded_at"]),
            };
            json!({"code": use_problem(&input["use"], &context).map(|(code, _)| code)})
        }
        "verify_export" => {
            let events = parse_export_lines(input["lines"].as_str().unwrap()).unwrap();
            let options = VerifyEvidenceOptions {
                contiguous: input["contiguous"].as_bool().unwrap_or(true),
                ..VerifyEvidenceOptions::new(
                    strings(&input["na_public_keys"]),
                    input["executor_keys"].as_array().unwrap().clone(),
                )
            };
            let result = verify_evidence_events(events.iter(), &options);
            let found: BTreeSet<(i64, String, Option<i64>)> = result
                .failures
                .iter()
                .map(|f| {
                    (
                        f.store_sequence.unwrap_or(0),
                        f.reason.clone(),
                        f.store_sequence,
                    )
                })
                .collect();
            let reported = serde_json::to_value(&result).unwrap();
            let counts: serde_json::Map<String, Value> = COUNTS
                .iter()
                .filter_map(|k| Some((k.to_string(), reported.get(*k)?.clone())))
                .collect();
            json!({
                "verified": result.verified,
                "failures": found.iter().map(|(_, reason, seq)| json!({
                    "store_sequence": seq, "reason": reason,
                })).collect::<Vec<_>>(),
                "counts": counts,
            })
        }
        other => panic!("unknown vector kind {other}"),
    }
}

#[test]
fn every_vector_gives_the_reference_outcome() {
    let suite = suite();
    assert_eq!(suite["suite"], "grants");
    let vectors = suite["vectors"].as_array().unwrap();
    assert_eq!(vectors.len(), 158);
    // The kinds only the NA runs (its issuance check, over the policy
    // engine): an SDK skips them.
    let na_only = &suite["na_only_kinds"];
    assert_eq!(*na_only, json!(["issuance"]));
    let (mut ran, mut skipped) = (0, 0);
    for v in vectors {
        if na_only.as_array().unwrap().contains(&v["kind"]) {
            skipped += 1;
            continue;
        }
        assert_eq!(evaluate(v), v["expected"], "{}", v["id"]);
        ran += 1;
    }
    assert_eq!((ran, skipped), (99, 59));
}

fn vector(id: &str) -> Value {
    suite()["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .find(|v| v["id"] == id)
        .unwrap_or_else(|| panic!("no vector {id}"))
        .clone()
}

fn na_key() -> String {
    vector("signature-CapabilityGrant-signer")["public_key"]
        .as_str()
        .unwrap()
        .to_owned()
}

fn bearer_key() -> String {
    vector("signature-GrantExecutionEvidence-signer")["public_key"]
        .as_str()
        .unwrap()
        .to_owned()
}

#[test]
fn the_sample_records_read_as_their_models() {
    for model in [
        "CapabilityGrant",
        "GrantExecutionEvidence",
        "GrantRevocationRecord",
        "TimeToken",
        "TimeTokenRequest",
    ] {
        let record = vector(&format!("canonical-{model}"))["record"].clone();
        assert!(valid_grant_record(model, &record), "{model}");
        let mut extra = record.clone();
        extra["x_added_field"] = json!(1);
        assert!(
            !valid_grant_record(model, &extra),
            "{model} with an extra field"
        );
    }
}

#[test]
fn a_grant_record_verifies_alone_by_kind() {
    let na = VerifyRecordOptions {
        na_public_keys: vec![na_key()],
        ..VerifyRecordOptions::default()
    };
    for (kind, model) in [
        ("grant", "CapabilityGrant"),
        ("grant_revocation", "GrantRevocationRecord"),
        ("time_token", "TimeToken"),
    ] {
        let record = vector(&format!("canonical-{model}"))["record"].clone();
        let result = verify_record(kind, &record, &na);
        assert!(result.verified, "{kind}: {:?}", result.failures);
        let mut tampered = record.clone();
        tampered["issued_by"] = json!("someone-else");
        if kind == "grant_revocation" {
            tampered["detail"] = json!("changed");
        }
        assert_eq!(
            verify_record(kind, &tampered, &na).reason,
            "invalid_signature",
            "{kind}"
        );
    }
    // A use: signed by its grant's bearer key, an executor key of its
    // sovereign; its time token by the NA.
    let record = vector("canonical-GrantExecutionEvidence")["record"].clone();
    let keys = json!([{
        "key_id": "executor-b", "public_key": bearer_key(),
        "executor_sovereign_id": record["executor_sovereign_id"], "role": "executor",
    }]);
    let options = VerifyRecordOptions {
        executor_keys: keys.as_array().unwrap().clone(),
        ..na.clone()
    };
    let result = verify_record("grant_execution", &record, &options);
    assert!(result.verified, "{:?}", result.failures);
    // Its token signed by another key than the NA's.
    let other = VerifyRecordOptions {
        na_public_keys: vec![bearer_key()],
        ..options.clone()
    };
    assert_eq!(
        verify_record("grant_execution", &record, &other).reason,
        "grant_time_token_invalid"
    );
    // An observer key does not sign a use.
    let mut observer = options.clone();
    observer.executor_keys[0]["role"] = json!("observer");
    assert_eq!(
        verify_record("grant_execution", &record, &observer).reason,
        "invalid_signature"
    );
}

#[test]
fn an_envelope_number_written_as_a_float_is_not_the_form_the_reference_writes() {
    // The same grant with `minimum: 1.0`: signed over that form, the
    // reference refuses it as `non_canonical_form`; this crate does too.
    use genesis_mesh_sdk::strict::non_canonical_fields;
    let mut record = vector("canonical-CapabilityGrant")["record"].clone();
    assert!(non_canonical_fields("CapabilityGrant", &record).is_empty());
    record["parameter_envelope"]["lifetime_days"]["number_range"]["minimum"] = json!(1.0);
    assert_eq!(
        non_canonical_fields("CapabilityGrant", &record),
        ["parameter_envelope.lifetime_days.number_range.minimum"]
    );
    let mut region = vector("canonical-CapabilityGrant")["record"].clone();
    region["parameter_envelope"]["region"]["one_of"] = json!(["eu-west", 2.0]);
    assert_eq!(
        non_canonical_fields("CapabilityGrant", &region),
        ["parameter_envelope.region.one_of.1"]
    );
    // A nested time token keeps no `use_head_digest: null`.
    let mut first = vector("use-admitted")["input"]["use"].clone();
    assert!(non_canonical_fields("GrantExecutionEvidence", &first).is_empty());
    first["time_token"]["use_head_digest"] = Value::Null;
    assert_eq!(
        non_canonical_fields("GrantExecutionEvidence", &first),
        ["time_token.use_head_digest"]
    );
}

#[test]
fn a_grant_digest_is_its_signed_form_as_received() {
    let input = vector("use-admitted")["input"].clone();
    assert_eq!(
        grant_digest(&input["grant"]).unwrap(),
        input["use"]["grant_digest"].as_str().unwrap()
    );
}

#[test]
fn the_revocation_feed_lists_revoked_grants_and_keeps_its_1_5_form_without_them() {
    for id in [
        "signature-feed-with-grants",
        "signature-feed-without-grants",
    ] {
        let v = vector(id);
        let key = v["public_key"].as_str().unwrap().to_owned();
        assert!(
            verify_revocation_feed(&v["record"], std::slice::from_ref(&key)),
            "{id}"
        );
        assert!(
            !verify_revocation_feed(&v["record"], &[bearer_key()]),
            "{id}"
        );
        let mut extra = v["record"].clone();
        extra["x_added_field"] = json!(1);
        assert!(!verify_revocation_feed(&extra, &[key]), "{id}");
    }
    let with = vector("signature-feed-with-grants")["record"].clone();
    assert_eq!(with["revoked_grant_ids"].as_array().unwrap().len(), 2);
    let without = vector("signature-feed-without-grants")["record"].clone();
    assert!(without.get("revoked_grant_ids").is_none());
}
